/* Categorised emporium. The free chest uses explicit trusted time, frontier, charge cap and idempotent review receipts. */
const ShopGiftsUI=(()=>{
    const G=MageFreeGifts,categories=[['gifts','Free gifts','chest-closed'],['cosmetics','Cosmetics','crowned'],['comfort','Comfort','lock']];let serial=0,reveal=null,timer=null,playToken=0,offset=0;
    // Review clock: the shared dungeon clock plus accelerated gift hours. Base cap 3; a later venture upgrade passes a higher cap.
    const now=()=>DungeonUI.clock()+offset,cap=()=>G.baseCap;
    const frontier=()=>MageFrontier.fromStep(RealmProgression.inspect().unlocked);
    const status=()=>G.status(state.freeGifts,now(),{cap:cap()});
    const countdown=()=>{const seconds=Math.max(0,Math.ceil((status().nextAt-now())/1000));return Math.floor(seconds/60)+'m '+String(seconds%60).padStart(2,'0')+'s';};
    const resetText=s=>s.nextAt===null?'Full · +1 every hour':'Next charge in '+countdown();
    function tabs(){return `<nav class="shop-categories" aria-label="Shop categories">${categories.map(([id,name,art])=>`<button data-shop-category="${id}" aria-pressed="${state.shopCategory===id}">${id==='gifts'?sprite(art):ui(art)}<span>${name}</span>${id==='gifts'&&status().available?'<i class="gift-ready-dot" aria-label="Free gift ready"></i>':''}</button>`).join('')}</nav>`;}
    const art=(tier,phase)=>sprite('chest-'+tier.key+'-'+phase);
    function odds(){return `<section class="rarity-odds chest-odds" aria-label="Free chest rarity chances"><div class="row"><strong>Chest chances</strong><small>100% total</small></div><div class="odds-bar" aria-hidden="true">${G.tiers.map(t=>`<i style="width:${t.odds/100}%;background:${t.color}"></i>`).join('')}</div><div class="odds-grid">${G.tiers.map(t=>`<div style="--rarity:${t.color}">${art(t,'closed')}<span>${t.name}</span><b>${t.odds/100}%</b></div>`).join('')}</div></section>`;}
    function celebration(receipt){if(!receipt||reveal?.owner!==state||reveal.id!==receipt.id)return '';const elapsed=performance.now()-reveal.started;if(elapsed>=reveal.duration)return '';const t=G.tiers[receipt.rarity];return `<div class="chest-celebration chest-rank-${receipt.rarity}" data-chest-reveal="${receipt.rarity}" aria-hidden="true" style="--reveal-duration:${reveal.duration}ms;--reveal-elapsed:-${elapsed}ms;--chest-color:${t.color}"><i class="chest-flare"></i>${receipt.rarity>=2?'<i class="chest-rune-ring"></i>':''}${receipt.rarity>=3?'<i class="chest-rays"></i>':''}<div class="reveal-chest"><span class="reveal-closed">${art(t,'closed')}</span><span class="reveal-open">${art(t,'open')}</span></div>${Array.from({length:[0,4,8,12,20][receipt.rarity]},(_,i)=>`<i class="chest-mote" style="--angle:${i*137.5}deg;--reach:${45+i%4*13}px">✦</i>`).join('')}<strong class="chest-reveal-name">${t.name}</strong></div>`;}
    function gift(){const s=status(),receipt=state.giftReceipt&&state.giftReceipt===s.receipt?s.receipt:null,t=receipt?G.tiers[receipt.rarity]:null,f=frontier(),range=G.preview(f),low=range[0],high=range.at(-1);return `<section class="daily-gift-card ${receipt?'gift-collected':''}" data-gift-charges="${s.charges}" ${t?`style="--chest-color:${t.color}"`:''}><div class="chest-summary"><div class="gift-figure" data-chest-state="${receipt?'open':'closed'}">${t?art(t,'open'):sprite('chest-closed')}</div><div class="chest-copy"><div class="gift-heading"><h3>Free chest</h3><span class="gift-tags"><span class="gift-charges" data-gift-stored aria-label="${s.charges} of ${s.cap} chest charges stored">${s.charges}/${s.cap}</span><span class="gift-free-tag">FREE</span></span></div><strong class="chest-result" role="status">${t?t.name+' chest':'Resource gift'}</strong><div class="gift-reward-preview" aria-label="${receipt?receipt.ore+' Ore and '+receipt.pearls+' Pearls':low.ore+' to '+high.ore+' Ore and '+low.pearls+' to '+high.pearls+' Pearls, depending on chest rarity'}">${metric('ore',receipt?'+'+receipt.ore:low.ore+'–'+high.ore,'Ore')}${metric('pearls',receipt?'+'+receipt.pearls:low.pearls+'–'+high.pearls,'Pearls')}</div></div></div>${odds()}<button class="rune-button" data-free-gift ${s.available?'':'disabled'}>${s.available?'Open · Free':s.valid?'Recharging':'Synchronize time'}</button><div class="gift-reset-line">${ui('time','inline-icon')}<span data-gift-reset>${resetText(s)}</span></div>${celebration(receipt)}</section><p class="gift-no-strings">No purchase · No streak · Scales with ${realms[f.realm]} tier ${f.tier}</p>`;}
    async function play(receipt){const owner=state;if(!receipt)return;const token=++playToken;clearTimeout(timer);reveal=null;const img=new Image();img.src='assets/chests-v20/'+G.tiers[receipt.rarity].key+'.png';await img.decode().catch(()=>{});if(token!==playToken||owner!==state||!(owner.freeGifts.receipts.includes(receipt)||owner.inventory.receipts.includes(receipt)&&receipt.action==='open'))return;const duration=matchMedia('(prefers-reduced-motion: reduce)').matches?200:G.tiers[receipt.rarity].duration;reveal={owner,id:receipt.id,started:performance.now(),duration};render(true);timer=setTimeout(()=>{if(reveal?.owner===owner&&reveal.id===receipt.id){reveal=null;if(state===owner)render(true);}},duration);}
    const claim=(id,sample)=>G.claim(state,{id,now:now(),sample,frontier:frontier(),cap:cap()});
    function reviewClaim(rarity){const out=claim('review-chest-'+rarity,(G.odds.slice(0,rarity).reduce((a,b)=>a+b,0)+G.odds[rarity]/2)/10000);if(out.ok){state.giftReceipt=out.receipt;play(out.receipt);}return out;}
    function productCard(p){const owned=state.shop.owned.includes(p.id),equipped=state.shop.equipped===p.id;return `<button class="shop-product ${owned?'owned':''}" data-shop-product="${p.id}" aria-label="${p.name}, ${p.type}, ${owned?'owned':p.price+'. Example price'}"><span class="product-sigil sigil-${p.id}">${ui(p.art)}</span><span class="product-copy"><strong>${p.name}</strong><small>${p.type}</small></span><b>${equipped?'Equipped':owned?'Owned':p.price}</b><span aria-hidden="true">›</span></button>`;}
    function view(){const category=state.shopCategory||'gifts';state.shopCategory=category;return `<section class="page shop-page categorised-shop"><div class="compact-heading">${title('Arcane Emporium')}<button class="text-button restore-purchases" data-shop-restore>Restore</button></div>${tabs()}${category==='gifts'?gift():`${category==='cosmetics'?`<div class="shop-mage-preview" data-cosmetic="${state.shop.equipped||''}">${sprite('mage')}<span>${state.shop.equipped?MageShop.products.find(p=>p.id===state.shop.equipped).name:'Your mage, your style'}</span></div>`:`<div class="comfort-preview" data-shop-empty>${ui('lock')}<span>No comfort items yet</span></div>`}<div class="shop-products">${MageShop.products.filter(p=>category==='cosmetics'?p.type==='Cosmetic':p.type!=='Cosmetic').map(productCard).join('')}</div><p class="shop-fairness">${ui('crest')} Style & comfort. Strength is earned.</p><small class="shop-demo">Example prices · Purchases are simulated</small>`}</section>`;}
    function handle(el){if(el.hasAttribute('data-chest-replay')){const receipt=status().receipt;if(receipt){state.modal=null;state.shopCategory='gifts';go('shop');play(receipt);}return true;}if(el.dataset.shopCategory){state.shopCategory=el.dataset.shopCategory;render(true);return true;}if(el.hasAttribute('data-gift-hour')){advanceHour();return true;}if(el.hasAttribute('data-free-gift')){const out=claim('free-chest-'+(++serial),Math.random());if(out.ok&&!out.duplicate){state.giftReceipt=out.receipt;render(true);play(out.receipt);}return true;}return false;}
    function advanceHour(){offset+=G.hourMs;render(true);}
    function tick(){const el=phone.querySelector('[data-gift-reset]');if(!el)return;const s=status(),card=phone.querySelector('.daily-gift-card');if(card.dataset.giftCharges!==String(s.charges)){render(true);return;}el.textContent=resetText(s);}
    return {view,handle,tick,status,frontier,claim,advanceHour,reviewClaim,play,celebration};
})();
